export function getCapodannoEventForClub(clubSlug: string, clubName?: string): CapodannoEventItem | undefined {
  const normalized = (clubSlug || '').toLowerCase().trim();
  const mappedSlug = CLUB_SLUG_TO_CAPODANNO_SLUG[normalized];
  if (mappedSlug) {
    const found = getCapodannoEventBySlug(mappedSlug);
    if (found) return found;
  }
  const tokens = normalized.split('-').filter((t) => t.length >= 3 && t !== 'milano' && t !== 'club' && t !== 'milan');
  for (const item of CAPODANNO_EVENTS) {
    const itemSlug = item.slug.toLowerCase();
    const itemVenue = item.venueName.toLowerCase();
    if (tokens.length > 0 && tokens.every((t) => itemSlug.includes(t) || itemVenue.includes(t))) {
      return item;
    }
    if (clubName && itemVenue.includes(clubName.toLowerCase().replace(/s+milano$/i, '').trim())) {
      return item;
    }
  }
  return undefined;
}
